def transform(grid):
    bg = grid[0][0]
    target = None

    for color in range(10):
        if color != bg:
            target = color
            break

    if target is None:
        return [[bg, bg], [bg, bg]]

    blocks = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows - 1):
        for c in range(cols - 1):
            if (grid[r][c] == target and grid[r][c+1] == target and
                grid[r+1][c] == target and grid[r+1][c+1] == target):
                blocks.append((r, c))

    if not blocks:
        return [[bg, bg], [bg, bg]]

    # Output is always 2x2 for 2x2 block patterns
    # Top-left, top-right, bottom-left, bottom-right of block positions

    # Determine which quadrant each block is in
    def quadrant(r, c):
        mid_r = rows // 2
        mid_c = cols // 2
        if r < mid_r and c < mid_c:
            return (0, 0),  # top-left
        if r < mid_r and c >= mid_c:
            return (0, 1),  # top-right
        if r >= mid_r and c < mid_c:
            return (1, 0),  # bottom-left
        if r >= mid_r and c >= mid_c:
            return (1, 1),  # bottom-right

    output = [[bg, bg], [bg, bg]]
    for block_r, block_c in blocks:
        qr, qc = quadrant(block_r, block_c)
        output[qr][qc] = target

    return output
